import { useState } from "react";
import { projects } from "../data/portfolio";
import { useScrollReveal } from "../hooks/useScrollReveal";

function ProjectCard({ project }) {
  const [expanded, setExpanded] = useState(false);
  const ref = useScrollReveal();

  return (
    <div ref={ref} className="fade-up border border-wire bg-ink-800 hover:border-ink-500 transition-all duration-300">
      {/* Header */}
      <div className="p-8 border-b border-wire">
        <div className="flex items-start justify-between gap-4 mb-4">
          <span className="font-mono text-xs text-stone-600">{project.id}</span>
          <span className="tag">{project.category}</span>
        </div>
        <h3 className="font-display font-bold text-stone-200 text-xl mb-4">{project.title}</h3>

        {/* Stack tags */}
        <div className="flex flex-wrap gap-2">
          {project.stack.map((t) => (
            <span key={t} className="tag text-accent-glow border-ink-600">{t}</span>
          ))}
        </div>
      </div>

      {/* Body */}
      <div className="p-8 grid md:grid-cols-2 gap-8">
        <div>
          <p className="font-mono text-xs text-stone-600 uppercase tracking-wider mb-2">Problem</p>
          <p className="text-stone-400 text-sm leading-relaxed">{project.problem}</p>
        </div>
        <div>
          <p className="font-mono text-xs text-stone-600 uppercase tracking-wider mb-2">Solution</p>
          <p className="text-stone-400 text-sm leading-relaxed">{project.solution}</p>
        </div>
      </div>

      {/* Expandable details */}
      {expanded && (
        <div className="px-8 pb-8 grid md:grid-cols-2 gap-8 border-t border-wire pt-8">
          <div>
            <p className="font-mono text-xs text-stone-600 uppercase tracking-wider mb-3">Key Features</p>
            <ul className="space-y-2">
              {project.features.map((f) => (
                <li key={f} className="flex items-start gap-2 text-sm text-stone-400">
                  <span className="text-accent-glow mt-1 text-xs flex-shrink-0">◆</span>
                  {f}
                </li>
              ))}
            </ul>
          </div>
          <div>
            <p className="font-mono text-xs text-stone-600 uppercase tracking-wider mb-3">Technical Highlights</p>
            <ul className="space-y-2">
              {project.highlights.map((h) => (
                <li key={h} className="flex items-start gap-2 text-sm text-stone-400">
                  <span className="text-accent-glow mt-1 text-xs flex-shrink-0">◆</span>
                  {h}
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}

      {/* Toggle */}
      <div className="px-8 pb-6">
        <button
          onClick={() => setExpanded(!expanded)}
          className="font-mono text-xs text-stone-500 hover:text-accent-glow transition-colors flex items-center gap-2 tracking-wider"
        >
          {expanded ? "— Collapse" : "+ Show Details"}
        </button>
      </div>
    </div>
  );
}

export default function Projects() {
  return (
    <section id="projects" className="py-28 border-t border-wire">
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Projects</p>
          <h2 className="section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl">
            Selected work.<br />
            <span className="text-stone-500">Architecture documented.</span>
          </h2>
          <p className="text-stone-500 text-sm mt-4 font-mono">
            Click "Show Details" on each project to see technical implementation notes.
          </p>
        </div>

        <div className="space-y-5">
          {projects.map((project) => (
            <ProjectCard key={project.id} project={project} />
          ))}
        </div>
      </div>
    </section>
  );
}
